function getAphgPristineUnitQuestion(unitNum, targetTopic, idx = 0) {
  let u = unitNum;
  if (!u && targetTopic) {
    const match = targetTopic.match(/unit\s*([1-7])/i);
    if (match) u = parseInt(match[1], 10);
  }
  if (!u || u < 1 || u > 7) {
    u = idx % 7 + 1;
  }
  const q = APHG_UNIT_PRISTINE_VAULT[u] || APHG_UNIT_PRISTINE_VAULT[1];
  return { ...q, id: idx + 1 };
}
